-- Criação da base de dados e da tabela, se não existirem
CREATE DATABASE IF NOT EXISTS scdatajor;

USE scdatajor;

CREATE TABLE IF NOT EXISTS dados (
    ID VARCHAR(255) PRIMARY KEY,
    Cidade VARCHAR(100),
    Regiao VARCHAR(100),
    Nome_Do_Curso VARCHAR(255),
    Turno VARCHAR(50),
    Site VARCHAR(255), -- Campo Site adicionado
    Modalidade VARCHAR(100),
    Categoria_Administrativa_Da_IES VARCHAR(255)
);

DESC dados;

SELECT * FROM dados;

